const normalizeProviderWarningKey = (value) => (readString(value) ?? '')
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase()
  .replace(/\s+/g, ' ');
const provisionalProviderWarningKeys = new Set(
  provisionalProviderWarnings.map(normalizeProviderWarningKey).filter(Boolean),
);
const finalWarnings = [
  ...new Set(
    warnings
      .map(readString)
      .filter(Boolean)
      .filter(
        (warning) =>
          !provider ||
          !provisionalProviderWarningKeys.has(normalizeProviderWarningKey(warning)),
      ),
  ),
];
const finalMetadata = {
  confidence: readNumber(metadata.confidence),
  warnings: finalWarnings,
  raw_text_summary: readString(metadata.raw_text_summary),
  document_kind: documentKind,
  pdf_sha256: readString(source.pdf_sha256),
  extraction_ok: shouldIngest,
  ready_for_review: shouldIngest,
  ready_for_edge_enrichment: readyForEdgeEnrichment,
  ready_for_erp: readyForErp,
  match_evidence: evidence,
};
const output = {
  extraction,
  gastos: gastosDraft,
  ctb: [],
  punteos: punteoSuggestions,
